INSERT INTO public.articulos VALUES (1, 1, 'Art. 6', 'Faltas Leves', 'Constituyen faltas leves las acciones u omisiones en el cumplimiento del deber que no causen daño grave.');
INSERT INTO public.articulos VALUES (2, 1, 'Art. 12', 'Formalidades del Memorándum', 'Todo memorándum debe contener firma de la autoridad, fecha fidedigna y número correlativo.');
INSERT INTO public.articulos VALUES (3, 2, 'Art. 24', 'Registro en Escalafón', 'Los reconocimientos y felicitaciones deberán remitirse al Comando General para su homologación.');
