INSERT INTO public.tipos_observacion VALUES (1, 'Falta sello y rúbrica formal', 'Falta la rúbrica y el sello institucional de la autoridad policial en el documento escaneado.');
INSERT INTO public.tipos_observacion VALUES (2, 'Fecha inconsistente', 'Inconsistencia temporal o desfase en las fechas consignadas en el trámite.');
INSERT INTO public.tipos_observacion VALUES (3, 'No coincide el número correlativo', 'El correlativo de memorándum no coincide con el libro de altas y bajas de la unidad.');
INSERT INTO public.tipos_observacion VALUES (4, 'Documento ilegible o baja resolución', 'Baja resolución de escaneo o contenido borroso que impide la lectura fehaciente.');
INSERT INTO public.tipos_observacion VALUES (5, 'Falta informe o foja de respaldo', 'Faltan fojas anexas, informes circunstanciados o respaldos del trámite.');
INSERT INTO public.tipos_observacion VALUES (6, 'Datos filiatorios discrepantes', 'Discrepancia en los datos de filiación, cédula de identidad, escalafón o grado del oficial.');
INSERT INTO public.tipos_observacion VALUES (7, 'Otro motivo administrativo', 'Observaciones de índole formal o administrativa general.');
